import{_ as e,c as t,o,ag as r}from"./chunks/framework.B3RpK1bM.js";const u=JSON.parse('{"title":"低代码开发","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/low-code-development-instructions.md","filePath":"zh_CN/low-code-development-instructions.md","lastUpdated":1770012448000}'),l={name:"zh_CN/low-code-development-instructions.md"};function n(i,a,s,h,d,c){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="低代码开发" tabindex="-1">低代码开发 <a class="header-anchor" href="#低代码开发" aria-label="Permalink to &quot;低代码开发&quot;">​</a></h1><p><a href="./">返回目录</a></p><h2 id="支持" tabindex="-1">支持 <a class="header-anchor" href="#支持" aria-label="Permalink to &quot;支持&quot;">​</a></h2><blockquote><p>由于android程序使用apk工具安装使用，原则上可以导出apk版本，但目前不便于打包分发。 故描述为当前<strong>低代码开发</strong>暂不支持android端。</p></blockquote><p>Ezgal支持windows与linux端，mac端可以自行通过godot导出开发模板。</p><h2 id="开发" tabindex="-1">开发 <a class="header-anchor" href="#开发" aria-label="Permalink to &quot;开发&quot;">​</a></h2><p>低代码开发无需配置godot与dotnet开发环境，原理是通过程序开放的接口对基础资源进行自定义, 需要下载预编译的初始ezgal创建目录进行开发.</p><h3 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h3><p>你可以直接获取对应系统的<a href="https://atomgit.com/godothub/ezgal/releases" target="_blank" rel="noreferrer">发行版</a>.</p><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h3><p>开放接口以文件夹形式进行管理，可参考<a href="/oss/ezgal/zh_CN/file-structure-description.html#框架结构/">框架结构</a>的<strong>低代码开发</strong>说明创建对应文件夹，剧本演出脚本可参考<a href="/oss/ezgal/zh_CN/syntax-design.html">语法设计</a>进行编写.</p><h3 id="低代码开发编辑器" tabindex="-1">低代码开发编辑器 <a class="header-anchor" href="#低代码开发编辑器" aria-label="Permalink to &quot;低代码开发编辑器&quot;">​</a></h3><p>ezgal定义了固定的解释语言，针对<strong>低代码开发</strong>的接口均以文本形式进行管理，未来初步规划开发ezgal编辑器便于开发设置等流程.</p><h3 id="案例" tabindex="-1">案例 <a class="header-anchor" href="#案例" aria-label="Permalink to &quot;案例&quot;">​</a></h3><p>以下是一些基于Ezgal的游戏开发案例：</p><ul><li><a href="https://atomgit.com/cryingn/The_Guilty_Secret" target="_blank" rel="noreferrer">The_Guilty_Secret</a></li></ul><h2 id="分发" tabindex="-1">分发 <a class="header-anchor" href="#分发" aria-label="Permalink to &quot;分发&quot;">​</a></h2><p>分发项目时应该打包初始ezgal程序与目录下的相关文件夹资源.</p>',18)])])}const _=e(l,[["render",n]]);export{u as __pageData,_ as default};
